#include <stdio.h>

// Function to get a value from an array
int getValueFromArray(int *array, int len, int index) {
	int value;
	// check that the array index is less than the maximum length of the array
	if (index < len) {
		// get the value at the specified index of the array
		value = array[index];
	} else {
		// if array index is invalid then output error message
		// and return value indicating error
		printf("Value is: %d\n", array[index]);
		value = -1;
	}
	return value;
}

#ifndef UNIT_TEST
// Main function
int main() {
	// Example array and index
	int array[] = {10, 20, 30, 40, 50};
	int index = 2;
	int len = sizeof(array) / sizeof(array[0]);

	// Call the function with the example array
	int value = getValueFromArray(array, len, index);
	printf("The retrieved value is: %d\n", value);

	return 0;
}
#endif

