// Test boundary condition with an out-of-bounds index.
void testBoundaryOutOfBounds() {
    int array[] = {10, 20, 30, 40, 50};
    int len = sizeof(array) / sizeof(array[0]);

    assert(getValueFromArray(array, len, len) == -1); // Index out of bounds
